<?php
$queue=query('SELECT a.id,a.score,d.title,d.sector,u.name AS owner,COUNT(DISTINCT r.criterion) AS reviewed FROM analyses a JOIN documents d ON d.id=a.document_id JOIN users u ON u.id=d.user_id LEFT JOIN reviews r ON r.analysis_id=a.id GROUP BY a.id,a.score,d.title,d.sector,u.name ORDER BY a.id DESC LIMIT 100')->fetchAll();
$selected=!empty($_GET['id'])?findAnalysis((int)$_GET['id'],$u):null;
?>
<div class="page-heading"><div><span class="eyebrow">İNSAN DENETİMİ, AÇIK GEREKÇELER</span><h1>Uzman incelemesi<span class="heading-dot">.</span></h1><p>Kriter bulgularını inceleyin ve gerekçeli değerlendirmenizi ekleyin.</p></div><span class="badge found"><?= e(roleName($u['role'])) ?></span></div>
<?php if(!empty($_GET['id'])&&!$selected): ?><div class="alert error">İncelenecek analiz bulunamadı.</div><?php endif ?>
<?php if($selected): $existing=query('SELECT * FROM reviews WHERE analysis_id=? AND expert_id=?',[$selected['id'],$u['id']])->fetchAll();$labels=array_column($existing,null,'criterion'); ?>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">RAPOR #<?= (int)$selected['id'] ?></span><h2><?= e($selected['title']) ?></h2><p><?= e($selected['owner']) ?> · <?= e($selected['sector']) ?></p></div><a class="text-link" href="<?= url('report',['id'=>$selected['id']]) ?>">Raporu aç <?= icon('arrow') ?></a></div><div class="expert-document"><?= nl2br(e($selected['content'])) ?></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Kriterleri etiketleyin</h2><p>Her kriteri ayrı kaydedin. Yeniden kaydetmek yalnızca kendi etiketinizi günceller.</p></div><span class="count-label"><?= count($labels) ?>/8 etiketiniz</span></div>
<div class="expert-criteria"><?php foreach($selected['result']['criteria'] as $key=>$c): $label=$labels[$key]??null; ?><details class="expert-criterion" <?= !$label?'open':'' ?>><summary><span><strong><?= e($c['title']) ?></strong><small><?= e($c['basis']) ?> · Motor: <?= e(statusName($c['status'])) ?></small></span><span class="badge <?= $label?'found':'partial' ?>"><?= $label?'Etiketiniz kaydedildi':'Değerlendirme bekliyor' ?></span></summary><form method="post" class="expert-form"><?= csrf() ?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="criterion" value="<?= e($key) ?>"><p class="muted"><?= e($c['advice']) ?></p><label>Uzman değerlendirmesi<select name="verdict" required><option value="">Karar seçin</option><?php foreach(['sufficient'=>'Yeterli','insufficient'=>'Yetersiz','uncertain'=>'Belirsiz / ek inceleme gerekli'] as $v=>$text): ?><option value="<?= $v ?>" <?= ($label['verdict']??'')===$v?'selected':'' ?>><?= $text ?></option><?php endforeach ?></select></label><label>Gerekçe ve metindeki dayanak<textarea name="note" required minlength="10" maxlength="2000" rows="3" placeholder="Değerlendirmenizi metindeki ilgili ifadelerle açıklayın."><?= e($label['note']??'') ?></textarea></label><button class="button small">Değerlendirmeyi kaydet</button></form></details><?php endforeach ?></div></section>
<?php endif ?>
<section class="panel"><div class="panel-heading"><div><h2>İnceleme kuyruğu</h2><p>En son 100 analiz · Etiket sayısı, en az bir uzmanın değerlendirdiği farklı kriterleri gösterir.</p></div></div><?php if(!$queue): ?><div class="empty"><p>İncelenecek analiz henüz bulunmuyor.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Belge</th><th>Belge sahibi</th><th>Skor</th><th>Etiketlenen kriter</th><th>İşlem</th></tr></thead><tbody><?php foreach($queue as $item): ?><tr><td><?= e($item['title']) ?></td><td><?= e($item['owner']) ?></td><td><?= (int)$item['score'] ?>/100</td><td><?= (int)$item['reviewed'] ?>/8</td><td><a class="text-link" href="<?= url('review',['id'=>$item['id']]) ?>">İncele <?= icon('arrow') ?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<?php if($u['role']==='admin'): $users=query('SELECT id,name,email,role FROM users ORDER BY id DESC LIMIT 100')->fetchAll(); ?><section class="panel"><div class="panel-heading"><div><span class="eyebrow">YÖNETİCİ ARAÇLARI</span><h2>Kullanıcı yetkileri</h2><p>Uzman yetkisini yalnızca değerlendirme sorumluluğu bulunan kullanıcılara verin.</p></div></div><div class="table-wrap"><table><thead><tr><th>Kullanıcı</th><th>E-posta</th><th>Rol</th><th>İşlem</th></tr></thead><tbody><?php foreach($users as $person): ?><tr><td><?= e($person['name']) ?></td><td><?= e($person['email']) ?></td><td><?= e(roleName($person['role'])) ?></td><td><?php if((int)$person['id']!==(int)$u['id']): ?><form method="post" class="role-form"><?= csrf() ?><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?= (int)$person['id'] ?>"><label class="visually-hidden" for="role-<?= (int)$person['id'] ?>"><?= e($person['name']) ?> rolü</label><select id="role-<?= (int)$person['id'] ?>" name="role"><?php foreach(['user','expert','admin'] as $role): ?><option value="<?= $role ?>" <?= $person['role']===$role?'selected':'' ?>><?= e(roleName($role)) ?></option><?php endforeach ?></select><button class="button secondary small">Kaydet</button></form><?php else: ?><span class="muted">Siz</span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
